import Foundation

public enum AdvPayloadDecoder {
    public struct Field: Sendable, Equatable { public let label:String; public let value:String; public init(_ label:String,_ value:String){self.label=label;self.value=value} }
    public struct RoleHint: Sendable, Equatable { public let bucket:String; public let label:String; public let reason:String; public let weight:Int; public init(bucket:String,label:String,reason:String,weight:Int){self.bucket=bucket;self.label=label;self.reason=reason;self.weight=weight} }

    public static func decodeManufacturer(_ record:MfgRecord)->[Field] {
        guard let b=hexToBytes(record.dataHex) else{return []}
        switch record.companyId { case 0x004C:return decodeApple(b); case 0x0006:return decodeMicrosoft(b); case 0x0157:return decodeAltBeacon(b); case 0x00E0:return [Field("Google manufacturer data","\(b.count) bytes")]; default:return [] }
    }
    public static func decodeService(_ record:ServiceDataRecord)->[Field] {
        guard let b=hexToBytes(record.dataHex),let u=uuid16(record.uuid) else{return []}
        switch u { case 0xFE2C:return decodeFastPair(b); case 0xFEAA:return decodeEddystone(b); default:return [] }
    }
    public static func roleHints(_ device:Sighting)->[RoleHint] {
        var out=[RoleHint]()
        let mfg=device.facts.mfgRecords.isEmpty ? (device.manufacturerId.map{[MfgRecord(companyId:$0,dataHex:device.manufacturerDataHex)]} ?? []) : device.facts.mfgRecords
        for rec in mfg where rec.companyId == 0x004C {
            guard let bytes=hexToBytes(rec.dataHex) else{continue}
            for t in appleTLVs(bytes) {
                switch t.type {
                case 0x02 where t.data.count >= 20:
                    // FIX-AD1: Kotlin يفرّق ثلاثة: Tesla (وزن 8) · Target/Atrius (وزن 8) · iBeacon عام (7).
                    let h=hex(t.data).uppercased(), tesla=DefaultCatalogConstants.teslaIBeaconMfgPrefix.uppercased()
                    let atrius=DefaultCatalogConstants.targetAtriusIBeaconMfgPrefix.uppercased()
                    if h.hasPrefix(tesla) || h.hasPrefix(String(tesla.dropFirst(4))) { out.append(RoleHint(bucket:"vehicle",label:"a Tesla vehicle or phone-as-key",reason:"Tesla phone-key iBeacon UUID (iOS background find).",weight:8)) }
                    else if h.hasPrefix(atrius) || h.hasPrefix(String(atrius.dropFirst(4))) { out.append(RoleHint(bucket:"beacon",label:"a Target Atrius basket tag",reason:"Target / Atrius iBeacon UUID (shopping-basket asset tag).",weight:8)) }
                    else { out.append(RoleHint(bucket:"beacon",label:"an iBeacon",reason:"Apple iBeacon payload.",weight:7)) }
                case 0x05: out.append(RoleHint(bucket:"phone",label:"an iPhone or iPad offering AirDrop",reason:"Apple AirDrop advertisement.",weight:5))
                case 0x07: let model=airPodsModel(t.data); out.append(RoleHint(bucket:"audio-personal",label:model ?? "AirPods or Beats headphones",reason:model == nil ? "Apple Proximity Pairing (AirPods / Beats)." : "Apple Proximity Pairing: \(model!).",weight:8))
                case 0x08: out.append(RoleHint(bucket:"siri",label:"an Apple device that just heard “Hey Siri”",reason:"Hey Siri advertisement.",weight:6))
                case 0x09: out.append(RoleHint(bucket:"audio-speaker",label:"an AirPlay speaker or Apple TV",reason:"AirPlay advertisement.",weight:5))
                case 0x0B: out.append(RoleHint(bucket:"phone",label:"an Apple device doing Handoff",reason:"Handoff advertisement.",weight:4))
                case 0x0C: out.append(RoleHint(bucket:"phone",label:"an Apple device looking for Instant Hotspot",reason:"Tethering-target advertisement.",weight:5))
                case 0x0D,0x0E: out.append(RoleHint(bucket:"hotspot",label:"an iPhone/iPad offering Instant Hotspot",reason:"Tethering-source advertisement.",weight:6))
                case 0x0F: out.append(RoleHint(bucket:"phone",label:"an Apple device (Nearby Action)",reason:nearbyActionReason(t.data),weight:4))
                case 0x10: out.append(RoleHint(bucket:"phone",label:"an iPhone / iPad / Mac (Nearby Info)",reason:nearbyInfoReason(t.data),weight:5))
                case 0x12: out.append(RoleHint(bucket:"tag",label:"a Find My network radio",reason:"Apple Offline Finding — AirTag, Find My accessory, or an Apple device locating itself.",weight:4))
                default: break
                }
            }
        }
        for sd in device.facts.serviceData {
            guard let u=uuid16(sd.uuid),let b=hexToBytes(sd.dataHex) else{continue}
            if u == 0xFE2C {
                // FIX-AD2: Kotlin يستدعي FastPairModels.name — الاسم إن وُجد بوزن 8، وإلا وزن 6.
                if b.count==3 {
                    let id=modelId24(b), nm=FastPairModels.name(id)
                    out.append(RoleHint(bucket:"audio-personal",
                        label:nm ?? "a Fast Pair accessory (often earbuds or a speaker)",
                        reason:nm != nil ? String(format:"Google Fast Pair model %@ (0x%06X), in pairing mode.",nm!,id)
                                         : String(format:"Google Fast Pair model 0x%06X, in pairing mode.",id),
                        weight:nm != nil ? 8 : 6))
                } else { out.append(RoleHint(bucket:"audio-personal",label:"a Fast Pair accessory already paired to someone",reason:"Google Fast Pair account-key broadcast (not in pairing mode).",weight:4)) } }
            if u == 0xFEAA { let f=b.first ?? 0; if f==0x40 || f==0x41 { out.append(RoleHint(bucket:"tag",label:"a Google Find Hub tag",reason:f==0x41 ? "Find Hub separated (unwanted-tracking) frame." : "Find Hub nearby frame.",weight:8)) } else { out.append(RoleHint(bucket:"beacon",label:"an Eddystone beacon",reason:"Eddystone service data.",weight:6)) } }
        }
        return out
    }

    private struct TLV { let type:Int; let data:[UInt8] }
