    private static func decodeApple(_ bytes:[UInt8])->[Field] {
        let tlvs=appleTLVs(bytes); guard !tlvs.isEmpty else{return [Field("Apple payload","\(bytes.count) bytes (unparsed)")]}; var out=[Field]()
        for t in tlvs { out.append(Field("Apple Continuity type",String(format:"0x%02X · %@",t.type,appleTypeName(t.type)))); switch t.type {
        case 2:out += decodeIBeacon(t.data); case 5:out += decodeAirDrop(t.data); case 6:out += [Field("HomeKit","\(t.data.count) bytes of HomeKit setup data")]; case 7:out += decodeAirPods(t.data); case 8:out += decodeHeySiri(t.data); case 9:out += [Field("AirPlay","This device is advertising as an AirPlay source or target.")]; case 10:out += [Field("Magic Switch","Apple Watch wrist / unlock related.")]; case 11:out += decodeHandoff(t.data); case 12:out += decodeHandoffOrTetherTarget(t.data); case 13,14:out += decodeTetherSource(t.data); case 15:out += decodeNearbyAction(t.data); case 16:out += decodeNearbyInfo(t.data); case 18:out += decodeFindMy(t.data); default:out += [Field("Payload","\(t.data.count) bytes")] }
        }; return out
    }
    private static func appleTypeName(_ t:Int)->String { [2:"iBeacon",3:"AirPrint",5:"AirDrop",6:"HomeKit",7:"Proximity Pairing (AirPods / Beats)",8:"Hey Siri",9:"AirPlay",10:"Magic Switch (Watch)",11:"Handoff",12:"Handoff or Instant Hotspot (target)",13:"Instant Hotspot (source)",14:"Instant Hotspot (source)",15:"Nearby Action",16:"Nearby Info",18:"Find My / Offline Finding",19:"Nearby Action (extended)",22:"Nearby Info"][t] ?? "unlisted" }
    private static func decodeIBeacon(_ data:[UInt8])->[Field] { let body=(data.count>=22 && data[0]==0x15) ? Array(data[1..<22]) : (data.count>=21 ? Array(data[0..<21]) : []); guard body.count>=21 else{return [Field("iBeacon","truncated (\(data.count) bytes)")]}; let uuid=uuidFromBE(body,0); let tesla=uuid.filter{$0.isLetter||$0.isNumber}.lowercased()==String(DefaultCatalogConstants.teslaIBeaconMfgPrefix.dropFirst(4)).lowercased(); return [Field("iBeacon UUID",tesla ? "\(uuid) — Tesla phone-as-key (iOS background find). Not a mall beacon." : uuid),Field("iBeacon major / minor","\(u16be(body,16)) / \(u16be(body,18))"),Field("iBeacon calibrated TX","\(Int(Int8(bitPattern:body[20]))) dBm at 1 m (used to estimate range)")] }
