    private static func decodeAirPods(_ data:[UInt8])->[Field] { guard data.count>=5 else{return [Field("AirPods","Proximity Pairing, truncated.")]}; let start=data[0]==1 ? 1:0; guard data.count>=start+4 else{return [Field("AirPods","Proximity Pairing.")]}; let model=Int(data[start])<<8|Int(data[start+1]), status=Int(data[start+2]), batt=Int(data[start+3]), left=batt&15,right=(batt>>4)&15; var out=[Field("Product",airPodsModelName(model) ?? String(format:"Apple audio 0x%04X",model)),Field("Pod position",airPodsStatus(status)),Field("Battery (left / right)","\(nibblePct(left)) / \(nibblePct(right))")]; if data.count>start+4 { let ch=Int(data[start+4]), cb=ch&15; out.append(Field("Case battery",nibblePct(cb))); var c=[String](); if ch&0x10 != 0{c.append("case")};if ch&0x20 != 0{c.append("right")};if ch&0x40 != 0{c.append("left")};if !c.isEmpty{out.append(Field("Charging",c.joined(separator:", ")))}};if data.count>start+6{out.append(Field("Color",airPodsColor(Int(data[start+6]))))};return out }
    private static func airPodsModel(_ data:[UInt8])->String? { guard data.count>=4 else{return nil};let s=data[0]==1 ? 1:0;guard data.count>=s+2 else{return nil};return airPodsModelName(Int(data[s])<<8|Int(data[s+1])) }
    private static func airPodsModelName(_ id:Int)->String? { [0x0220:"AirPods (1st generation)",0x0F20:"AirPods (2nd generation)",0x1320:"AirPods (3rd generation)",0x1920:"AirPods (4th generation)",0x1C20:"AirPods 4",0x0E20:"AirPods Pro",0x1420:"AirPods Pro (2nd generation)",0x2420:"AirPods Pro 2 (USB-C)",0x1F20:"AirPods Max",0x0A20:"Beats Solo3",0x0B20:"Powerbeats 3",0x0C20:"Beats Studio Buds",0x0D20:"Beats Fit Pro",0x1020:"Powerbeats Pro",0x1120:"Beats Studio Buds +",0x1220:"Beats Solo Pro",0x1720:"Beats Flex",0x1A20:"Beats Studio Pro",0x1B20:"Beats Fit Pro",0x0520:"BeatsX",0x0920:"Beats Studio³ Wireless",0x1620:"Beats Studio Buds +",0x2520:"Beats Solo 4",0x2620:"Beats Solo Buds",0x2D20:"AirPods Max 2",0x3820:"Beats 360",0x038F:"Beats Studio Buds"][id] }
    private static func airPodsStatus(_ s:Int)->String { [1:"One or both out of the case",2:"Case open",3:"Taken out / in-ear transition",5:"One in ear",9:"Both out, not in ear",11:"In-ear activity",17:"Both in ear",19:"Both in ear",33:"One in ear (sharing?)",81:"Both in case, lid open",85:"Both in case, lid closed",117:"In case"][s] ?? String(format:"Status 0x%02X",s) }
    private static func airPodsColor(_ v:Int)->String { [0:"White",1:"Black",2:"Red",3:"Blue",4:"Pink",5:"Gray",6:"Silver",7:"Gold",8:"Rose gold",9:"Space gray",10:"Dark blue",11:"Light blue",12:"Yellow"][v] ?? String(format:"0x%02X",v) }
