    private static func nearbyActionName(_ a:Int)->String { [1:"Apple TV setup",4:"Mobile backup",5:"Watch setup",6:"Apple TV pair",8:"Wi-Fi password sharing (prompting nearby iPhones)",9:"iOS setup",10:"Repair",11:"Speaker setup",12:"Apple Pay",13:"Whole-home audio setup",15:"Answered a call",16:"Ended a call",19:"Remote AutoFill",20:"Companion Link proximity",23:"Remote display"][a] ?? String(format:"action 0x%02X",a) }
